    mandiTrend(trendStr, lang = null) {
      const l = lang || this.getLang();
      if (!trendStr || l === "en") return trendStr || "";
      const s = trendStr.toLowerCase();
      const pctMatch = trendStr.match(/\([+\-\d.,%\s]+\)/);
      const pct = pctMatch ? ` ${pctMatch[0].trim()}` : "";
      const word = s.includes("bullish") ? {
        hi: "तेजी", kn: "ಏರಿಕೆ", mr: "तेजी", te: "పెరుగుదల", ta: "உயர்வு", gu: "તેજી", bn: "ঊর্ধ্বমুখী", ml: "ഉയർച്ച", pa: "ਤੇਜ਼ੀ", or: "ବୃଦ୍ଧି"
      }[l] : (s.includes("active") ? {
        hi: "सक्रिय आवक", kn: "ಸಕ್ರಿಯ ಆವಕ", mr: "सक्रिय आवक", te: "చురుకైన రాబడి", ta: "சுறுசுறுப்பான வரத்து", gu: "સક્રિય આવક", bn: "সক্রিয় আমদানি", ml: "സജീവ വരവ്", pa: "ਸਰਗਰਮ ਆਮਦ", or: "ସକ୍ରିୟ ଆମଦାନୀ"
      }[l] : (s.includes("firm") ? {
        hi: "मजबूत", kn: "ಸ್ಥಿರ ಏರಿಕೆ", mr: "मजबूत", te: "దృఢమైనది", ta: "உறுதி", gu: "મજબૂત", bn: "দৃঢ়", ml: "ശക്തം", pa: "ਮਜ਼ਬੂਤ", or: "ଦୃଢ଼"
      }[l] : {
        hi: "स्थिर", kn: "ಸ್ಥಿರ", mr: "स्थिर", te: "స్థిరం", ta: "நிலையானது", gu: "સ્થિર", bn: "স্থিতিশীল", ml: "സ്ഥിരം", pa: "ਸਥਿਰ", or: "ସ୍ଥିର"
      }[l]));
      return `${word}${pct}`;
    },

