    localizeSource(src, lang = null) {
      const l = lang || this.getLang();
      if (!src || l === "en") return src || "";
      const s = String(src).toLowerCase();
      if (s.includes("snapshot")) return this.t("src_camera_snap", l);
      if (s.includes("camera")) return this.t("src_camera_photo", l);
      return this.t("src_uploaded_img", l);
    },

